const automationAdmin=["Super Admin","Admin"];

// Organizer control-tower snapshot: panel readiness, current interviews and
// candidates who can use each panel without violating completed-domain rules.
app.get("/api/events/:id/automation/orchestration",requireDb,requireAuth,requireRole(...eventOpsAdmin),async(req,res)=>{
 try{
  const panels=await pool.query("SELECT p.id,p.name,d.name AS domain,COUNT(DISTINCT pa.interviewer_id) FILTER(WHERE pa.active=true AND u.active=true)::int AS active_interviewers,MAX(u.display_name) FILTER(WHERE pa.active=true AND u.active=true) AS interviewer_name,COUNT(DISTINCT pc.id) FILTER(WHERE pc.status IN ('pending','sent'))::int AS pending_calls,COUNT(DISTINCT i.id) FILTER(WHERE i.status='in_progress')::int AS active_interviews,MAX(c.name) FILTER(WHERE i.status='in_progress') AS current_candidate,COUNT(DISTINCT c2.id) FILTER(WHERE c2.status IN ('waiting_1','waiting_2') AND NOT EXISTS(SELECT 1 FROM interviews done WHERE done.candidate_id=c2.id AND done.domain_id=p.domain_id AND done.status IN ('in_progress','completed')) AND NOT EXISTS(SELECT 1 FROM panel_calls openpc WHERE openpc.candidate_id=c2.id AND openpc.status IN ('pending','sent','started')))::int AS eligible_waiting FROM panels p JOIN domains d ON d.id=p.domain_id LEFT JOIN panel_assignments pa ON pa.panel_id=p.id LEFT JOIN users u ON u.id=pa.interviewer_id LEFT JOIN interviews i ON i.panel_id=p.id AND i.status='in_progress' LEFT JOIN candidates c ON c.id=i.candidate_id LEFT JOIN candidates c2 ON c2.event_id=p.event_id WHERE p.event_id=$1 AND p.active=true GROUP BY p.id,d.name ORDER BY p.name",[req.params.id]);
  const waiting=await pool.query("SELECT c.id,c.name,c.candidate_code,c.status,c.checked_in_at,c.created_at,EXTRACT(EPOCH FROM (now()-COALESCE(c.checked_in_at,c.created_at)))::int AS waiting_seconds,COUNT(cp.domain_id) FILTER(WHERE NOT EXISTS(SELECT 1 FROM interviews i WHERE i.candidate_id=c.id AND i.domain_id=cp.domain_id AND i.status IN ('in_progress','completed')))::int AS remaining_preferences,COALESCE(json_agg(json_build_object('domain',d.name,'priority',cp.priority) ORDER BY cp.priority) FILTER(WHERE NOT EXISTS(SELECT 1 FROM interviews i WHERE i.candidate_id=c.id AND i.domain_id=cp.domain_id AND i.status IN ('in_progress','completed'))),'[]'::json) AS remaining FROM candidates c LEFT JOIN candidate_preferences cp ON cp.candidate_id=c.id LEFT JOIN domains d ON d.id=cp.domain_id WHERE c.event_id=$1 AND c.status IN ('waiting_1','waiting_2') GROUP BY c.id ORDER BY CASE c.status WHEN 'waiting_2' THEN 0 ELSE 1 END,c.checked_in_at NULLS LAST,c.created_at LIMIT 100",[req.params.id]);
  const totals=await pool.query("SELECT COUNT(*) FILTER(WHERE status IN ('waiting_1','waiting_2'))::int AS waiting,COUNT(*) FILTER(WHERE status='called_to_panel')::int AS called,COUNT(*) FILTER(WHERE status='interviewing')::int AS interviewing,COUNT(*) FILTER(WHERE status='interviewed')::int AS completed FROM candidates WHERE event_id=$1",[req.params.id]);
  res.json({panels:panels.rows,waiting:waiting.rows,totals:totals.rows[0]||{waiting:0,called:0,interviewing:0,completed:0},updatedAt:new Date().toISOString()});
 }catch(e){console.error("Orchestration snapshot failed:",e);res.status(500).json({error:"Could not load live orchestration status."})}
});
